def plain(s):return html.unescape(re.sub('<[^>]+>','',re.sub(r'<br\s*/?>','\n',str(s),flags=re.I)))
def e(s):return html.escape(str(s),quote=True)
def internal(page,epub=False):return f'ch{int(page):02}.xhtml' if epub else f'#page-{int(page)}'
def body(c,epub=False):
    if c['page']==1:return '<figure class="coverfigure"><img src="'+('assets/cover.png' if epub else '../outputs/book-assets/cover.png')+'" alt="Cape Town housing opportunity report cover"/></figure>'
    if c['page']==2:return '<nav aria-label="Report contents"><ol class="contents">'+''.join(f'<li><a href="{internal(x["page"],epub)}">{e(x["title"])} <span>{x["page"]}</span></a></li>' for x in chapters[2:])+'</ol></nav>'
    parts=[];blocks=c['blocks']
    for i,b in enumerate(blocks):
        t=b['type']
        if t=='text' and i+1<len(blocks) and blocks[i+1]['type']=='link' and b['text']==blocks[i+1]['text']:continue
        if t=='heading':parts.append('<h3>'+e(b['text'])+'</h3>')
        elif t in ['paragraph','text']:
            s=plain(b.get('html',b.get('text','')))
            parts.append('<p'+(' class="caption"' if b.get('size',10)<8 else '')+'>'+e(s).replace('\n','<br/>')+'</p>')
        elif t=='metric':parts.append('<div class="metric"><strong>'+e(b['value'])+'</strong><span>'+e(b['label'])+'</span></div>')
        elif t in ['map','image']:
            asset=b['asset'];url='assets/'+asset if epub else ('../outputs/book-assets/'+asset if t=='map' else '../outputs/'+b['path'])
            alt='Map for '+c['title'] if t=='map' else Path(asset).stem.replace('-',' ')
            parts.append(f'<figure><img src="{e(url)}" alt="{e(alt)}"/><figcaption>{e(alt)}. Sources and limitations are described in the accompanying text.</figcaption></figure>')
        elif t=='link':parts.append(f'<p><a href="{e(b["url"])}">{e(b["text"])}</a></p>')
        elif t=='table':
            header=''.join('<th scope="col">'+e(x)+'</th>' for x in b['headers']);rows=[]
            for row in b['rows']:
                cells=[]
                for j,v in enumerate(row):
                    val=e(v)
                    if ('page' in b['headers'][j].lower() or b['headers'][j]=='Metro map') and re.fullmatch(r'[0-9, ]+',str(v)):
                        val=', '.join(f'<a href="{internal(n.strip(),epub)}">{e(n.strip())}</a>' for n in str(v).split(','))
                    cells.append('<td>'+val+'</td>')
                rows.append('<tr>'+''.join(cells)+'</tr>')
            parts.append('<div class="tablewrap"><table><thead><tr>'+header+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>')
    return '\n'.join(parts)
