def home_url(match):
    attr,url=match.groups()
    if url.startswith(('#','/')) or re.match(r'[a-zA-Z][a-zA-Z0-9+.-]*:',url):return match.group(0)
    return attr+'="'+posixpath.normpath('docs/'+url)+'"'
